if [[ -z "${PHOENIX_LOG_DIR+x}" ]]; then
  PHOENIX_LOG_DIR="${PHOENIX_LOG_DIR_DEFAULT}"
fi
readonly PHOENIX_LOG_DIR
export PHOENIX_LOG_DIR

# GNU awk
if [[ "${PHOENIX_OS}" == 'osx' ]]; then
  readonly PHOENIX_AWK_DEFAULT='gawk'
else
  readonly PHOENIX_AWK_DEFAULT='awk'
fi
if [[ -z "${PHOENIX_AWK+x}" ]]; then
  PHOENIX_AWK="${PHOENIX_AWK_DEFAULT}"
fi
readonly PHOENIX_AWK
export PHOENIX_AWK

# GNU sed
if [[ "${PHOENIX_OS}" == 'osx' ]]; then
  readonly PHOENIX_SED_DEFAULT='gsed'
else
  readonly PHOENIX_SED_DEFAULT='sed'
fi
if [[ -z "${PHOENIX_SED+x}" ]]; then
  PHOENIX_SED="${PHOENIX_SED_DEFAULT}"
fi
readonly PHOENIX_SED
export PHOENIX_SED

# GNU tar
if [[ "${PHOENIX_OS}" == 'osx' ]]; then
  readonly PHOENIX_TAR_DEFAULT='gtar'
else
  readonly PHOENIX_TAR_DEFAULT='tar'
fi
if [[ -z "${PHOENIX_TAR+x}" ]]; then
  PHOENIX_TAR="${PHOENIX_TAR_DEFAULT}"
fi
readonly PHOENIX_TAR
export PHOENIX_TAR

# Python
readonly PHOENIX_PYTHON_DIR_DEFAULT="${PHOENIX_EXTERNAL}/python"
if [[ -z "${PHOENIX_PYTHON_DIR+x}" ]]; then
  PHOENIX_PYTHON_DIR="${PHOENIX_PYTHON_DIR_DEFAULT}"
fi
readonly PHOENIX_PYTHON_DIR
export PHOENIX_PYTHON_DIR

# Python (UV) environment
readonly PHOENIX_PYENV_DIR_DEFAULT="${PHOENIX_BUILD}/pyenv"
if [[ -z "${PHOENIX_PYENV_DIR+x}" ]]; then
  PHOENIX_PYENV_DIR="${PHOENIX_PYENV_DIR_DEFAULT}"
fi
readonly PHOENIX_PYENV_DIR
readonly PHOENIX_PYENV="${PHOENIX_PYENV_DIR}/bin/activate"
export PHOENIX_PYENV
export PHOENIX_PYENV_DIR

if [[ "${PHOENIX_NIX}" == 1 ]]; then
  ## Nix doesn't want/need to set a specific Python path, see discussion at https://codeberg.org/celenity/Dove/issues/59
  ## and https://codeberg.org/celenity/Phoenix/issues/252
  readonly PHOENIX_PYTHON_DEFAULT='python'
else
  readonly PHOENIX_PYTHON_DEFAULT="${PHOENIX_PYENV_DIR}/bin/python"
fi
if [[ -z "${PHOENIX_PYTHON+x}" ]]; then
  PHOENIX_PYTHON="${PHOENIX_PYTHON_DEFAULT}"
fi
readonly PHOENIX_PYTHON
export PHOENIX_PYTHON

# UV
readonly PHOENIX_UV_DIR_DEFAULT="${PHOENIX_EXTERNAL}/uv"
if [[ -z "${PHOENIX_UV_DIR+x}" ]]; then
  PHOENIX_UV_DIR="${PHOENIX_UV_DIR_DEFAULT}"
fi
readonly PHOENIX_UV_DIR
readonly PHOENIX_UV="${PHOENIX_UV_DIR}/uv"
export PHOENIX_UV
export PHOENIX_UV_DIR

# UV (local directory)
readonly PHOENIX_UV_LOCAL_DEFAULT="${PHOENIX_BUILD}/uv"
if [[ -z "${PHOENIX_UV_LOCAL+x}" ]]; then
  PHOENIX_UV_LOCAL="${PHOENIX_UV_LOCAL_DEFAULT}"
fi
readonly PHOENIX_UV_LOCAL
export PHOENIX_UV_LOCAL

# UV cache
readonly PHOENIX_UV_CACHE_DEFAULT="${PHOENIX_UV_LOCAL}/cache"
if [[ -z "${PHOENIX_UV_CACHE+x}" ]]; then
  PHOENIX_UV_CACHE="${PHOENIX_UV_CACHE_DEFAULT}"
fi
readonly PHOENIX_UV_CACHE
export PHOENIX_UV_CACHE

# UV Python directory
readonly PHOENIX_UV_PYTHON_DEFAULT="${PHOENIX_UV_LOCAL}/python"
if [[ -z "${PHOENIX_UV_PYTHON+x}" ]]; then
  PHOENIX_UV_PYTHON="${PHOENIX_UV_PYTHON_DEFAULT}"
fi
readonly PHOENIX_UV_PYTHON
export PHOENIX_UV_PYTHON

# UV tools
readonly PHOENIX_UV_TOOLS_DEFAULT="${PHOENIX_UV_LOCAL}/tools"
if [[ -z "${PHOENIX_UV_TOOLS+x}" ]]; then
  PHOENIX_UV_TOOLS="${PHOENIX_UV_TOOLS_DEFAULT}"
fi
readonly PHOENIX_UV_TOOLS
export PHOENIX_UV_TOOLS

# Cipher suites
## (This enforces strong cipher suites - see ex. https://browserleaks.com/tls)
readonly PHOENIX_CIPHERS_DEFAULT='TLS_AES_128_GCM_SHA256:TLS_CHACHA20_POLY1305_SHA256:TLS_AES_256_GCM_SHA384:ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384'
if [[ -z "${PHOENIX_CIPHERS+x}" ]]; then
  PHOENIX_CIPHERS="${PHOENIX_CIPHERS_DEFAULT}"
fi
readonly PHOENIX_CIPHERS
export PHOENIX_CIPHERS

# If curl flags are added, this determines whether they should be appended to our default flags (default),
## or if they should override them entirely
readonly PHOENIX_CURL_FLAGS_OVERRIDE_DEFAULT=0
if [[ -z "${PHOENIX_CURL_FLAGS_OVERRIDE+x}" ]]; then
  PHOENIX_CURL_FLAGS_OVERRIDE="${PHOENIX_CURL_FLAGS_OVERRIDE_DEFAULT}"
fi
readonly PHOENIX_CURL_FLAGS_OVERRIDE
export PHOENIX_CURL_FLAGS_OVERRIDE

# curl flags
readonly PHOENIX_CURL_FLAGS_DEFAULT="-q --disable --no-netrc -j -e "" -A "" -S --ciphers ${PHOENIX_CIPHERS} --clobber --create-dirs --delegation none --disallow-username-in-url --doh-cert-status --ftp-create-dirs --ftp-ssl-control --junk-session-cookies --no-basic --no-ca-native --no-digest --no-doh-insecure --no-http0.9 --no-insecure --no-proxy-insecure --no-negotiate --no-ntlm --no-proxy-basic --no-proxy-ca-native --no-proxy-digest --no-proxy-insecure --no-proxy-ssl-allow-beast --no-proxy-ssl-auto-client-cert --no-sessionid --no-skip-existing --no-ssl --no-ssl-allow-beast --no-ssl-auto-client-cert --no-ssl-no-revoke --no-ssl-revoke-best-effort --no-tls-earlydata --no-xattr --progress-meter --proto -all,https --proto-default https --proto-redir -all,https --referer "" --remove-on-error --show-error --ssl-reqd --tlsv1.2 --trace-time --user-agent "" --verbose"
if [[ -z "${PHOENIX_CURL_FLAGS+x}" ]]; then
  readonly PHOENIX_CURL_FLAGS="${PHOENIX_CURL_FLAGS_DEFAULT}"
elif [[ "${PHOENIX_CURL_FLAGS_OVERRIDE}" == 1 ]]; then
  readonly PHOENIX_CURL_FLAGS="${PHOENIX_CURL_FLAGS}"
else
  readonly PHOENIX_CURL_FLAGS="${PHOENIX_CURL_FLAGS_DEFAULT} ${PHOENIX_CURL_FLAGS}"
fi
export PHOENIX_CURL_FLAGS

# Whether we're ONLY building Phoenix for Android
readonly PHOENIX_ANDROID_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_ANDROID_ONLY+x}" ]]; then
  PHOENIX_ANDROID_ONLY="${PHOENIX_ANDROID_ONLY_DEFAULT}"
fi
readonly PHOENIX_ANDROID_ONLY
export PHOENIX_ANDROID_ONLY
if [ "${PHOENIX_ANDROID_ONLY}" == 1 ]; then
  PHOENIX_ANDROID=1
  PHOENIX_LINUX=0
  PHOENIX_LINUX_FLATPAK=0
  PHOENIX_OSX=0
  PHOENIX_OSX_INTEL=0
  PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for Linux
readonly PHOENIX_LINUX_ONLY_DEFAULT=0
if [ "${PHOENIX_NIX}" == 1 ] && [ "${PHOENIX_OS}" != 'osx' ]; then
  # Nix flakes should only build their respective platform
  PHOENIX_LINUX_ONLY=1
elif [[ -z "${PHOENIX_LINUX_ONLY+x}" ]]; then
  PHOENIX_LINUX_ONLY="${PHOENIX_LINUX_ONLY_DEFAULT}"
fi
readonly PHOENIX_LINUX_ONLY
export PHOENIX_LINUX_ONLY
if [ "${PHOENIX_LINUX_ONLY}" == 1 ]; then
  PHOENIX_LINUX=1
  PHOENIX_ANDROID=0
  PHOENIX_LINUX_FLATPAK=0
  PHOENIX_OSX=0
  PHOENIX_OSX_INTEL=0
  PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for Linux (Flatpak)
readonly PHOENIX_LINUX_FLATPAK_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_LINUX_FLATPAK_ONLY+x}" ]]; then
  PHOENIX_LINUX_FLATPAK_ONLY="${PHOENIX_LINUX_FLATPAK_ONLY_DEFAULT}"
fi
readonly PHOENIX_LINUX_FLATPAK_ONLY
export PHOENIX_LINUX_FLATPAK_ONLY
if [ "${PHOENIX_LINUX_FLATPAK_ONLY}" == 1 ]; then
  PHOENIX_LINUX_FLATPAK=1
  PHOENIX_ANDROID=0
  PHOENIX_LINUX=0
  PHOENIX_OSX=0
  PHOENIX_OSX_INTEL=0
  PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for OS X
readonly PHOENIX_OSX_ONLY_DEFAULT=0
if [ "${PHOENIX_NIX}" == 1 ] && [ "${PHOENIX_OS}" == 'osx' ]; then
  # Nix flakes should only build their respective platform
  PHOENIX_OSX_ONLY=1
elif [[ -z "${PHOENIX_OSX_ONLY+x}" ]]; then
  PHOENIX_OSX_ONLY="${PHOENIX_OSX_ONLY_DEFAULT}"
fi
readonly PHOENIX_OSX_ONLY
export PHOENIX_OSX_ONLY
if [ "${PHOENIX_OSX_ONLY}" == 1 ]; then
  PHOENIX_OSX=1
  PHOENIX_ANDROID=0
  PHOENIX_LINUX=0
  PHOENIX_LINUX_FLATPAK=0
