readonly PHOENIX_OSX_INTEL_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_OSX_INTEL_ONLY+x}" ]]; then
  PHOENIX_OSX_INTEL_ONLY="${PHOENIX_OSX_INTEL_ONLY_DEFAULT}"
fi
readonly PHOENIX_OSX_INTEL_ONLY
export PHOENIX_OSX_INTEL_ONLY
if [ "${PHOENIX_OSX_INTEL_ONLY}" == 1 ]; then
  PHOENIX_OSX_INTEL=1
  PHOENIX_ANDROID=0
  PHOENIX_LINUX=0
  PHOENIX_LINUX_FLATPAK=0
  PHOENIX_OSX=0
  PHOENIX_WINDOWS=0
fi

# Whether we're ONLY building Phoenix for Windows
readonly PHOENIX_WINDOWS_ONLY_DEFAULT=0
if [[ -z "${PHOENIX_WINDOWS_ONLY+x}" ]]; then
  PHOENIX_WINDOWS_ONLY="${PHOENIX_WINDOWS_ONLY_DEFAULT}"
fi
readonly PHOENIX_WINDOWS_ONLY
export PHOENIX_WINDOWS_ONLY
if [ "${PHOENIX_WINDOWS_ONLY}" == 1 ]; then
  PHOENIX_WINDOWS=1
  PHOENIX_ANDROID=0
  PHOENIX_LINUX=0
  PHOENIX_LINUX_FLATPAK=0
  PHOENIX_OSX=0
